+// Avoid DLPack conversion for ordinary NumPy float64 inputs. Non-contiguous
+// arrays and other numeric dtypes retain the normal conversion path.
+class GravityInputVector {
+ public:
+  explicit GravityInputVector(nb::handle value) {
+    if (PyObject_GetBuffer(value.ptr(), &buffer_,
+                           PyBUF_STRIDES | PyBUF_FORMAT) == 0) {
+      if (buffer_.ndim == 1 && buffer_.itemsize == sizeof(double) &&
+          buffer_.format && std::strcmp(buffer_.format, "d") == 0 &&
+          (!buffer_.suboffsets || buffer_.suboffsets[0] < 0) &&
+          (buffer_.shape[0] <= 1 || buffer_.strides[0] == sizeof(double)) &&
+          reinterpret_cast<std::uintptr_t>(buffer_.buf) % alignof(double) ==
+              0) {
+        data_ = static_cast<const double*>(buffer_.buf);
+        size_ = buffer_.shape[0];
+        return;
+      }
+      PyBuffer_Release(&buffer_);
+    } else {
+      PyErr_Clear();
+    }
+    nb::object native = nb::module_::import_("numpy").attr("asarray")(
+        value, nb::arg("dtype") = "float64");
+    if (!nb::try_cast<Eigen::VectorXd>(native, copy_)) {
+      throw nb::type_error("positions must be a one-dimensional array");
+    }
+    data_ = copy_.data();
+    size_ = copy_.size();
+  }
+  ~GravityInputVector() {
+    if (buffer_.obj) {
+      PyBuffer_Release(&buffer_);
+    }
+  }
+  GravityInputVector(const GravityInputVector&) = delete;
+  GravityInputVector& operator=(const GravityInputVector&) = delete;
+  Eigen::Map<const Eigen::VectorXd> map() const { return {data_, size_}; }
+
+ private:
+  Py_buffer buffer_{};
+  Eigen::VectorXd copy_;
+  const double* data_;
+  Eigen::Index size_;
+};
+
+nb::object gravity_array(const Eigen::VectorXd& value, nb::handle empty) {
+  nb::object result = empty(value.size());
+  Py_buffer buffer;
+  if (PyObject_GetBuffer(result.ptr(), &buffer, PyBUF_WRITABLE) != 0) {
+    throw nb::python_error();
+  }
+  if (value.size() != 0) {
+    std::memcpy(buffer.buf, value.data(), value.size() * sizeof(double));
+  }
+  PyBuffer_Release(&buffer);
+  return result;
+}
