+  if (prepare) {
+    prepare_gravity_cache(joint_ids);
+  }
+  auto& bodies = gravity_cache_.bodies;
+  const Scalar rotation_tolerance =
+      Scalar(64) * std::numeric_limits<Scalar>::epsilon();
+  bool individual_coms = !gravity_cache_.rigid_transforms;
+  for (auto& body : bodies) {
+    const auto& pose = get_link_pose(joint_child_link_ids_[body.joint_id]);
+    body.position = pose.trans().template head<2>();
+    body.moment = (pose.quat() * body.first_moment).template head<2>();
+    body.axis = pose.quat() * joint_axes_[body.joint_id];
+    individual_coms |=
+        std::abs(pose.quat().squaredNorm() - Scalar(1)) > rotation_tolerance;
+  }
+  // Approximate FK can produce non-unit quaternions, whose vector actions do
+  // not compose as rigid rotations. Preserve the original formula in that
+  // case by evaluating COMs in world coordinates, without changing core FK.
+  if (individual_coms) {
+    for (auto& body : bodies) {
+      body.moment.setZero();
+    }
+    for (size_t k = 0; k < com_link_ids_.size(); ++k) {
+      const int owner = gravity_cache_.com_owners[k];
+      if (owner < 0) {
