-
+  // Only the horizontal first moment is needed for gravity along world -Z.
+  // Shift moments between joint origins, avoiding large absolute moments.
+  for (size_t i = bodies.size(); i-- > 0;) {
+    auto& body = bodies[i];
+    body.torque = joint_types_[body.joint_id] == urdf::Joint::PRISMATIC
+                      ? -Scalar(9.80665) * body.subtree_mass * body.axis.z()
+                      : Scalar(9.80665) * (body.axis.y() * body.moment.x() -
+                                           body.axis.x() * body.moment.y());
+    if (body.parent >= 0) {
+      auto& parent = bodies[body.parent];
+      parent.moment +=
+          body.moment + body.subtree_mass * (body.position - parent.position);
+    }
+  }
+  for (size_t i = 0; i < joint_ids.size(); ++i) {
