+template <typename Scalar>
+void KinematicModel<Scalar>::prepare_gravity_cache(
+    const std::vector<size_t>& joint_ids) {
+  const size_t n_link = link_parent_link_ids_.size();
+  std::vector<int> selected(n_link, -1);
+  for (size_t jid : joint_ids) {
+    if (jid >= joint_types_.size()) {
+      throw std::invalid_argument("invalid joint id");
+    }
+    selected[joint_child_link_ids_[jid]] = static_cast<int>(jid);
+  }
+  GravityCache cache;
+  cache.joint_ids = joint_ids;
+  cache.masses = link_masses_;
+  std::vector<int> owner(n_link, -1);
+  std::vector<Transform> to_owner(n_link, Transform::Identity());
+  // Existing link IDs are parent before child. Unrequested joints are fixed
+  // at their current positions, so their transforms can be folded once.
+  for (size_t lid = 0; lid < n_link; ++lid) {
+    if (lid == root_link_id_) {
+      continue;
+    }
+    const size_t parent = link_parent_link_ids_[lid];
+    if (selected[lid] >= 0) {
+      GravityBody body;
+      body.joint_id = selected[lid];
+      body.parent = owner[parent];
+      owner[lid] = static_cast<int>(cache.bodies.size());
+      cache.bodies.push_back(body);
+    } else {
+      owner[lid] = owner[parent];
+      to_owner[lid] = to_owner[parent] * tf_plink_to_hlink_cache_[lid];
+    }
+  }
+  for (size_t k = 0; k < com_link_ids_.size(); ++k) {
+    const size_t lid = com_link_ids_[k];
+    cache.com_owners.push_back(owner[lid]);
+    if (owner[lid] < 0) {
+      continue;
+    }
+    auto& body = cache.bodies[owner[lid]];
+    const auto& pose = to_owner[lid];
+    body.mass += link_masses_[k];
+    body.first_moment += link_masses_[k] *
+                         (pose.trans() + pose.quat() * com_local_positions_[k]);
+  }
+  for (auto& body : cache.bodies) {
+    body.subtree_mass = body.mass;
+  }
+  for (size_t i = cache.bodies.size(); i-- > 0;) {
+    const auto& body = cache.bodies[i];
+    if (body.parent >= 0) {
+      cache.bodies[body.parent].subtree_mass += body.subtree_mass;
+    }
+  }
+  for (size_t jid : joint_ids) {
+    cache.output_bodies.push_back(owner[joint_child_link_ids_[jid]]);
+  }
+  for (size_t jid = 0; jid < joint_types_.size(); ++jid) {
+    if (selected[joint_child_link_ids_[jid]] < 0) {
+      cache.locked_joint_ids.push_back(jid);
+      cache.locked_transforms.push_back(
+          tf_plink_to_hlink_cache_[joint_child_link_ids_[jid]]);
+      cache.rigid_transforms &=
+          std::abs(cache.locked_transforms.back().quat().squaredNorm() -
+                   Scalar(1)) <=
+          Scalar(64) * std::numeric_limits<Scalar>::epsilon();
+    }
+  }
+  cache.valid = true;
+  gravity_cache_ = std::move(cache);
+}
